/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import hashlib
seen={}
for p in sorted(Path('.').glob('pair-*')):
 for v in ['original','A','B']:
  for f in sorted((p/v).rglob('*')):
   if not f.is_file(): continue
   h=hashlib.sha256(f.read_bytes()).hexdigest()
   if h in seen: print(f'{f}: identical to {seen[h]}')
   else:
    seen[h]=str(f)
    print('\\n'+str(f))
    if p.name in ['pair-2','pair-3'] or int(p.name[5:])>=5:
     print(''.join(f'{i}: {s}\\n' for i,s in enumerate(f.read_text().splitlines(),1)))
PY"

