7:   async collect(parcel: Parcel): Promise<QuoteResult> {
8:     validateParcel(parcel);
9:     const batches = await Promise.allSettled(this.carriers.map(async carrier =>
10:       carrier.quote(copyParcel(parcel))));
11:     const options: DeliveryOption[] = [];
12:     const failedCarrierIds: string[] = [];
13:     for (const [index, batch] of batches.entries()) {
14:       const carrier = this.carriers[index]!;
15:       if (batch.status === 'rejected') {
16:         failedCarrierIds.push(carrier.id);
17:         continue;
18:       }
19:       for (const rate of batch.value) {
20:         if (isUsableRate(rate)) {
21:           options.push({
22:             carrierId: carrier.id,
23:             service: rate.service,
24:             amountCents: rate.amountCents,
25:             days: rate.days,
26:           });
27:         }
28:       }
29:     }
30:     options.sort(compareOptions);
31:     return { options, failedCarrierIds };
32:   }
33: }


