1: import { Catalog } from './catalog.js';
2: import type { CartLine, CartQuote, PricedLine } from './model.js';
3: import { addCents, promotionDiscount, validateLine } from './policy.js';
4: 
5: export interface QuoteRequest {
6:   lines: readonly CartLine[];
7:   promotionCode?: string;
8: }
9: 
10: export class CartPricing {
11:   constructor(private readonly catalog: Catalog) {}
12: 
13:   quote(request: QuoteRequest): CartQuote {
14:     const lines: PricedLine[] = [];
15:     let subtotalCents = 0;
16:     for (const line of request.lines) {
17:       validateLine(line);
18:       const product = this.catalog.product(line.sku);
19:       const lineCents = addCents(0, product.unitCents * line.quantity);
20:       subtotalCents = addCents(subtotalCents, lineCents);
21:       lines.push({
22:         sku: line.sku,
23:         quantity: line.quantity,
24:         unitCents: product.unitCents,
25:         subtotalCents: lineCents,
26:       });
27:     }
28:     const promotion = request.promotionCode === undefined
29:       ? undefined : this.catalog.promotion(request.promotionCode);
30:     let discountCents = 0;
31:     let appliedCode: string | null = null;
32:     if (promotion && subtotalCents >= promotion.minimumEligibleCents) {
33:       discountCents = promotionDiscount(subtotalCents, promotion);
34:       if (discountCents > 0) appliedCode = promotion.code;
35:     }
36:     return {
37:       lines,
38:       subtotalCents,
39:       discountCents,
40:       totalCents: subtotalCents - discountCents,
41:       appliedCode,
42:     };
43:   }
44: }


