1: import type { Product, Promotion } from './model.js';
2: import { validateProduct, validatePromotion } from './policy.js';
3: 
4: export class Catalog {
5:   private readonly products = new Map<string, Product>();
6:   private readonly promotions = new Map<string, Promotion>();
7: 
8:   constructor(products: readonly Product[], promotions: readonly Promotion[]) {
9:     for (const product of products) {
10:       validateProduct(product);
11:       this.products.set(product.sku, { ...product });
12:     }
13:     for (const promotion of promotions) {
14:       validatePromotion(promotion);
15:       this.promotions.set(promotion.code, { ...promotion });
16:     }
17:   }
18: 
19:   product(sku: string): Product {
20:     const product = this.products.get(sku);
21:     if (!product) throw new Error(`Unknown SKU: ${sku}`);
22:     return { ...product };
23:   }
24: 
25:   promotion(code: string): Promotion | undefined {
26:     const promotion = this.promotions.get(code);
27:     return promotion ? { ...promotion } : undefined;
28:   }
29: }


