     1	import type { Carrier, DeliveryOption, Parcel, QuoteResult } from './model.js';
     2	import { compareOptions, copyParcel, isUsableRate, validateParcel } from './policy.js';
     3	
     4	export class DeliveryQuotes {
     5	  constructor(private readonly carriers: readonly Carrier[]) {}
     6	
     7	  async collect(parcel: Parcel): Promise<QuoteResult> {
     8	    validateParcel(parcel);
     9	    const batches = await Promise.allSettled(this.carriers.map(async carrier => {
    10	      const rates = await carrier.quote(copyParcel(parcel));
    11	      const options: DeliveryOption[] = [];
    12	      for (const rate of rates) {
    13	        if (isUsableRate(rate)) {
    14	          options.push({
    15	            carrierId: carrier.id,
    16	            service: rate.service,
    17	            amountCents: rate.amountCents,
    18	            days: rate.days,
    19	          });
    20	        }
    21	      }
    22	      return options;
    23	    }));
    24	    const options: DeliveryOption[] = [];
    25	    const failedCarrierIds: string[] = [];
    26	    batches.forEach((batch, index) => {
    27	      if (batch.status === 'fulfilled') {
    28	        for (const option of batch.value) {
    29	          options.push(option);
    30	        }
    31	      } else {
    32	        // allSettled preserves the configured carrier order.
    33	        failedCarrierIds.push(this.carriers[index]!.id);
    34	      }
    35	    });
    36	    options.sort(compareOptions);
    37	    return { options, failedCarrierIds };
    38	  }
    39	}
