     2	import { compareOptions, copyParcel, isUsableRate, validateParcel } from './policy.js';
     3	
     4	export class DeliveryQuotes {
     5	  constructor(private readonly carriers: readonly Carrier[]) {}
     6	
     7	  async collect(parcel: Parcel): Promise<QuoteResult> {
     8	    validateParcel(parcel);
     9	    const batches = await Promise.allSettled(this.carriers.map(async carrier =>
    10	      carrier.quote(copyParcel(parcel))));
    11	    const options: DeliveryOption[] = [];
    12	    const failedCarrierIds: string[] = [];
    13	    for (const [index, batch] of batches.entries()) {
    14	      // allSettled preserves the configured carrier order.
    15	      const carrier = this.carriers[index]!;
    16	      if (batch.status === 'rejected') {
    17	        failedCarrierIds.push(carrier.id);
    18	        continue;
    19	      }
    20	      for (const rate of batch.value) {
    21	        if (isUsableRate(rate)) {
    22	          options.push({
    23	            carrierId: carrier.id,
    24	            service: rate.service,
    25	            amountCents: rate.amountCents,
    26	            days: rate.days,
    27	          });
    28	        }
    29	      }
    30	    }
    31	    options.sort(compareOptions);
    32	    return { options, failedCarrierIds };
    33	  }
    34	}

