     1	import type { CartLine, Product, Promotion } from './model.js';
     2	
     3	export function validateLine(line: CartLine): void {
     4	  if (!line.sku || !Number.isSafeInteger(line.quantity) || line.quantity < 1) {
     5	    throw new RangeError('Invalid cart line');
     6	  }
     7	}
     8	
     9	export function validateProduct(product: Product): void {
    10	  if (!Number.isSafeInteger(product.unitCents) || product.unitCents < 0) {
    11	    throw new RangeError('Invalid product price');
    12	  }
    13	}
    14	
    15	export function validatePromotion(promotion: Promotion): void {
    16	  if (!promotion.code || !Number.isInteger(promotion.percent)
    17	    || promotion.percent < 1 || promotion.percent > 100
    18	    || !Number.isSafeInteger(promotion.minimumEligibleCents)
    19	    || promotion.minimumEligibleCents < 0
    20	    || (promotion.maximumDiscountCents !== undefined
    21	      && (!Number.isSafeInteger(promotion.maximumDiscountCents)
    22	        || promotion.maximumDiscountCents < 0))) {
    23	    throw new RangeError('Invalid promotion');
    24	  }
    25	}
    26	
    27	export function addCents(a: number, b: number): number {
    28	  const total = a + b;
    29	  if (!Number.isSafeInteger(total) || total < 0) {
    30	    throw new RangeError('Cart amount exceeds supported range');
    31	  }
    32	  return total;
    33	}
    34	
    35	// Discounts round down once for the supplied base, then apply the cap.
    36	export function promotionDiscount(baseCents: number, promotion: Promotion): number {
    37	  const rounded = Number(BigInt(baseCents) * BigInt(promotion.percent) / 100n);
    38	  return Math.min(rounded, promotion.maximumDiscountCents ?? rounded);
    39	}
